import icontract
from typing import List


@icontract.ensure(lambda s, result: len(s) == len(result) and all(
    s[i] == result[i] for i in range(len(s))))
def iter_copy(s: List[int]) -> List[int]:
    result = []
    for x in s:
        result.append(x)
    return result
